import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:uuid/uuid.dart';\nimport '../../../core/providers/core_providers.dart';\nimport '../../announcements/models/announcement.dart';\nimport '../../announcements/providers/announcement_providers.dart';\n\nclass AddAnnouncementScreen extends ConsumerStatefulWidget {\n  const AddAnnouncementScreen({Key? key}) : super(key: key);\n\n  @override\n  ConsumerState<AddAnnouncementScreen> createState() => _AddAnnouncementScreenState();\n}\n\nclass _AddAnnouncementScreenState extends ConsumerState<AddAnnouncementScreen> {\n  final _formKey = GlobalKey<FormState>();\n  final _titleController = TextEditingController();\n  final _contentController = TextEditingController();\n  bool _isPriority = false;\n  bool _isLoading = false;\n\n  @override\n  void dispose() {\n    _titleController.dispose();\n    _contentController.dispose();\n    super.dispose();\n  }\n\n  Future<void> _submit() async {\n    if (!_formKey.currentState!.validate()) return;\n\n    setState(() => _isLoading = true);\n\n    try {\n      // In a real app, fetch schoolId from teacher's profile\n      final schoolId = 'dummy_school_id';\n\n      final announcement = Announcement(\n        id: const Uuid().v4(),\n        schoolId: schoolId,\n        title: _titleController.text.trim(),\n        content: _contentController.text.trim(),\n        createdAt: DateTime.now(),\n        priority: _isPriority,\n        isDeleted: false,\n      );\n\n      await ref.read(announcementServiceProvider).addAnnouncement(announcement);\n\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        const SnackBar(content: Text('تم نشر الإعلان بنجاح')),\n      );\n      Navigator.pop(context);\n    } catch (e) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(content: Text('خطأ: $e'), backgroundColor: Colors.red),\n      );\n    } finally {\n      if (mounted) setState(() => _isLoading = false);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('إضافة إعلان جديد')),\n      body: _isLoading\n          ? const Center(child: CircularProgressIndicator())\n          : SingleChildScrollView(\n              padding: const EdgeInsets.all(16.0),\n              child: Form(\n                key: _formKey,\n                child: Column(\n                  crossAxisAlignment: CrossAxisAlignment.stretch,\n                  children: [\n                    TextFormField(\n                      controller: _titleController,\n                      decoration: const InputDecoration(labelText: 'عنوان الإعلان', border: OutlineInputBorder()),\n                      validator: (val) => val == null || val.isEmpty ? 'مطلوب' : null,\n                    ),\n                    const SizedBox(height: 16),\n                    TextFormField(\n                      controller: _contentController,\n                      maxLines: 5,\n                      decoration: const InputDecoration(labelText: 'نص الإعلان', border: OutlineInputBorder()),\n                      validator: (val) => val == null || val.isEmpty ? 'مطلوب' : null,\n                    ),\n                    const SizedBox(height: 16),\n                    SwitchListTile(\n                      title: const Text('إعلان عاجل / هام', style: TextStyle(fontWeight: FontWeight.bold, color: Colors.red)),\n                      subtitle: const Text('سيظهر باللون الأحمر للفت الانتباه'),\n                      value: _isPriority,\n                      onChanged: (val) => setState(() => _isPriority = val),\n                      activeColor: Colors.red,\n                    ),\n                    const SizedBox(height: 32),\n                    ElevatedButton(\n                      onPressed: _submit,\n                      style: ElevatedButton.styleFrom(padding: const EdgeInsets.symmetric(vertical: 16)),\n                      child: const Text('نشر الإعلان', style: TextStyle(fontSize: 18)),\n                    )\n                  ],\n                ),\n              ),\n            ),\n    );\n  }\n}\n